class Solution:
    def isSubsequence(self, s: str, t: str) -> bool:
        def dfs(i: int, j: int) -> bool:
            if i == len(s):
                return True
            if j == len(t):
                return False
            if s[i] == t[j] and dfs(i + 1, j + 1):
                return True
            return dfs(i, j + 1)

        return dfs(0, 0)

solutions.better:
class Solution:
    def isSubsequence(self, s: str, t: str) -> bool:
        start = 0
        for ch in s:
            pos = t.find(ch, start)
            if pos == -1:
                return False
            start = pos + 1
        return True

